(2, 1, 2, 'https://medium.com/@amowogbajeflorence/episode-2-the-song-and-the-princess-a7aebf219e55', NULL, 0, 0, NULL, '2026-07-02 12:16:17', '2026-07-02 12:16:17', '{\"b\": \"20260701-1919-root\", \"v\": 3, \"payload\": {\"mode\": \"canEdit\", \"value\": {\"id\": \"a7aebf219e55\", \"slug\": \"episode-2-the-song-and-the-princess\", \"type\": \"Post\", \"vote\": false, \"title\": \"EPISODE 2: THE SONG AND THE PRINCESS\", \"content\": {\"subtitle\": \"Series: The Song of Kael\", \"bodyModel\": {\"sections\": [{\"name\": \"d784\", \"startIndex\": 0}, {\"name\": \"19a0\", \"startIndex\": 14}, {\"name\": \"b719\", \"startIndex\": 19}, {\"name\": \"2dfa\", \"startIndex\": 23}], \"paragraphs\": [{\"name\": \"abac\", \"text\": \"EPISODE 2: THE SONG AND THE PRINCESS\", \"type\": 3, \"markups\": []}, {\"name\": \"bbb7\", \"text\": \"Series: The Song of Kael\", \"type\": 1, \"markups\": [{\"end\": 24, \"type\": 2, \"start\": 0}]}, {\"name\": \"a656\", \"text\": \"Layali wore a cloak too plain for a princess, slipping past guards and servants with the elegance only rebellion could teach. She knew the castle’s every corridor — but not the paths beyond its walls.\", \"type\": 1, \"markups\": []}, {\"name\": \"d0a6\", \"text\": \"Tonight, her curiosity was louder than her duty.\", \"type\": 1, \"markups\": []}, {\"name\": \"83ed\", \"text\": \"The melody had returned.\", \"type\": 1, \"markups\": []}, {\"name\": \"ef07\", \"text\": \"Not from the palace, not from a bard’s chamber, but from beyond the city — somewhere deep in the valley where commoners grazed livestock and burned their hands in the sun.\", \"type\": 1, \"markups\": []}, {\"name\": \"f88c\", \"text\": \"And there he was.\", \"type\": 1, \"markups\": []}, {\"name\": \"7396\", \"text\": \"Kael sat cross-legged beneath a flame tree, his harp resting on his thigh like it had grown from him. His face was partially shadowed, but his voice — his voice carried clarity and ache. He didn’t notice her at first. He only sang:\", \"type\": 1, \"markups\": []}, {\"name\": \"02c2\", \"text\": \"“Elohim, my hands were made for iron\\n But they have found strings instead.\\n Teach me how to war in the spirit,\\n And not lose the heart in my chest.”\", \"type\": 6, \"markups\": []}, {\"name\": \"980d\", \"text\": \"Layali forgot how to breathe.\", \"type\": 1, \"markups\": []}, {\"name\": \"02eb\", \"text\": \"This was not a song for crowds. This was confession, longing, prophecy all tangled together. She had read of seers and sages — but never imagined a shepherd could hold such sacred weight in his voice.\", \"type\": 1, \"markups\": []}, {\"name\": \"a4eb\", \"text\": \"Kael sensed her then.\", \"type\": 1, \"markups\": []}, {\"name\": \"82a6\", \"text\": \"He rose, immediately alert, eyes narrowing like a wolf sensing movement in the trees. His hand flicked near his waist — instinct reaching for a hidden blade. But she stepped into the light.\", \"type\": 1, \"markups\": []}, {\"name\": \"a8a6\", \"text\": \"And everything shifted.\", \"type\": 1, \"markups\": []}, {\"name\": \"a886\", \"text\": \"“You’re the one who sings,” she said.\", \"type\": 6, \"markups\": [{\"end\": 37, \"type\": 2, \"start\": 0}]}, {\"name\": \"6020\", \"text\": \"“I didn’t mean to be heard,” he replied. His voice wasn’t defensive — just layered, like a soldier who’d long stopped trying to explain himself.\", \"type\": 6, \"markups\": [{\"end\": 144, \"type\": 2, \"start\": 0}]}, {\"name\": \"23b9\", \"text\": \"“Why do you sing like that? Like you’re praying while bleeding.”\", \"type\": 6, \"markups\": [{\"end\": 64, \"type\": 2, \"start\": 0}]}, {\"name\": \"45f9\", \"text\": \"Kael hesitated.\", \"type\": 1, \"markups\": []}, {\"name\": \"1e86\", \"text\": \"“Because I am.”\", \"type\": 6, \"markups\": [{\"end\": 15, \"type\": 2, \"start\": 0}]}, {\"name\": \"e9e9\", \"text\": \"They talked long after the stars blinked into place — not of royalty or war, but of loneliness, of divine whispers, of a world beyond blades and crowns. She didn’t say who she was, and he didn’t ask.\", \"type\": 1, \"markups\": []}, {\"name\": \"be7f\", \"text\": \"For once, they were just a man and a woman, standing at the edge of something neither fully understood.\", \"type\": 1, \"markups\": []}, {\"name\": \"320c\", \"text\": \"But heaven understood.\", \"type\": 1, \"markups\": []}, {\"name\": \"8e2c\", \"text\": \"“Elohim,” Kael whispered that night, “why do You send me kings’ daughters and songs that burn?”\", \"type\": 6, \"markups\": []}, {\"name\": \"c195\", \"text\": \"🕊️ To be continued…\", \"type\": 1, \"markups\": [{\"end\": 20, \"type\": 2, \"start\": 4}]}]}, \"postDisplay\": {\"coverless\": true}}, \"license\": 0, \"cardType\": 0, \"isSeries\": false, \"seoTitle\": \"\", \"virtuals\": {\"tags\": [{\"name\": \"War\", \"slug\": \"war\", \"type\": \"Tag\", \"metadata\": {\"postCount\": 59320, \"coverImage\": {\"id\": \"1*fZ_GsxvwDOPFaXsoV59KLw.png\", \"originalWidth\": 1178, \"originalHeight\": 800}}, \"postCount\": 59320}, {\"name\": \"Warriors\", \"slug\": \"warriors\", \"type\": \"Tag\", \"metadata\": {\"postCount\": 1377, \"coverImage\": {\"id\": \"0*ENyN09fOu9j6F8bM\", \"originalWidth\": 7823, \"originalHeight\": 4792, \"unsplashPhotoId\": \"8MhejqEghLk\"}}, \"postCount\": 1377}, {\"name\": \"Romance Novels\", \"slug\": \"romance-novels\", \"type\": \"Tag\", \"metadata\": {\"postCount\": 3449, \"coverImage\": {\"id\": \"1*5Vlc3hvagHQr-JYMiiFVZw.png\", \"alt\": \"15 Days Before I Left Him _ Novel\", \"originalWidth\": 607, \"originalHeight\": 793}}, \"postCount\": 3449}, {\"name\": \"Elohim\", \"slug\": \"elohim\", \"type\": \"Tag\", \"metadata\": {\"postCount\": 128, \"coverImage\": {\"id\": \"1*Xc8_fjd93KgC1LlFepGvjA.jpeg\", \"alt\": \"Stone relief of 2 Sumerian Gods facing each other and holding a cup and tools\", \"originalWidth\": 768, \"originalHeight\": 432}}, \"postCount\": 128}], \"links\": {\"entries\": [], \"version\": \"0.3\", \"generatedAt\": 1749806987728}, \"topics\": [{\"name\": \"Fiction\", \"slug\": \"fiction\", \"type\": \"Topic\", \"image\": {\"id\": \"1*s8IiITC03I9AcUb8aJQG_w@2x.jpeg\", \"originalWidth\": 6016, \"originalHeight\": 4000}, \"topicId\": \"76d64bb2132c\", \"seoTitle\": \"Fiction Writing — Medium\", \"createdAt\": 1491495941661, \"deletedAt\": 0, \"visibility\": 1, \"description\": \"True lies.\", \"relatedTags\": [], \"relatedTopics\": [], \"relatedTopicIds\": []}], \"noIndex\": false, \"subtitle\": \"Series: The Song of Kael\", \"wordCount\": 376, \"allowNotes\": true, \"imageCount\": 0, \"recommends\": 0, \"readingList\": 2, \"readingTime\": 1.4188679245283018, \"isBookmarked\": true, \"previewImage\": {\"width\": 0, \"filter\": \"\", \"height\": 0, \"imageId\": \"\", \"strategy\": \"resample\", \"originalWidth\": 0, \"backgroundSize\": \"\", \"originalHeight\": 0}, \"sectionCount\": 4, \"totalClapCount\": 0, \"metaDescription\": \"\", \"userPostRelation\": {\"postId\": \"a7aebf219e55\", \"readAt\": 1749809073507, \"userId\": \"5d9c968bd96d\", \"votedAt\": 0, \"queuedAt\": 1749808360461, \"viewedAt\": 1750453674313, \"clapCount\": 0, \"lastReadAt\": 0, \"notesAddedAt\": 0, \"subscribedAt\": 0, \"audioProgressSec\": 0, \"readLaterAddedAt\": 1749808360461, \"lastReadVersionId\": \"\", \"lastReadPercentage\": 0, \"seriesLastViewedAt\": 0, \"collaboratorAddedAt\": 0, \"lastReadSectionName\": \"\", \"seriesFirstViewedAt\": 0, \"lastReadParagraphName\": \"\", \"seriesUpdateNotifsOptedInAt\": 0}, \"isLockedPreviewOnly\": false, \"responsesCreatedCount\": 0, \"socialRecommendsCount\": 0, \"usersBySocialRecommends\": []}, \"coverless\": true, \"createdAt\": 1749550550291, \"creatorId\": \"5d9c968bd96d\", \"deletedAt\": 0, \"latestRev\": 131, \"layerCake\": 0, \"mediumUrl\": \"https://medium.com/@amowogbajeflorence/episode-2-the-song-and-the-princess-a7aebf219e55\", \"socialDek\": \"\", \"updatedAt\": 1749810548917, \"versionId\": \"2a24d9cab79f\", \"acceptedAt\": 0, \"sequenceId\": \"\", \"uniqueSlug\": \"episode-2-the-song-and-the-princess-a7aebf219e55\", \"visibility\": 0, \"importedUrl\": \"\", \"isProxyPost\": false, \"isShortform\": false, \"isSuspended\": false, \"migrationId\": \"\", \"socialTitle\": \"\", \"canonicalUrl\": \"https://medium.com/@amowogbajeflorence/episode-2-the-song-and-the-princess-a7aebf219e55\", \"isNewsletter\": false, \"newsletterId\": \"\", \"displayAuthor\": \"\", \"latestVersion\": \"2a24d9cab79f\", \"notifyTwitter\": false, \"proxyPostType\": 0, \"shortformType\": 0, \"allowResponses\": true, \"isLimitedState\": false, \"notifyFacebook\": false, \"previewContent\": {\"subtitle\": \"Series: The Song of Kael\", \"bodyModel\": {\"sections\": [{\"startIndex\": 0}], \"paragraphs\": [{\"name\": \"abac\", \"text\": \"EPISODE 2: THE SONG AND THE PRINCESS\", \"type\": 3, \"markups\": [], \"alignment\": 1}, {\"name\": \"bbb7\", \"text\": \"Series: The Song of Kael\", \"type\": 1, \"markups\": [{\"end\": 24, \"type\": 2, \"start\": 0}], \"alignment\": 1}, {\"name\": \"a656\", \"text\": \"Layali wore a cloak too plain for a princess, slipping past guards and servants with the elegance only rebellion could teach. She knew the castle’s every corridor — but not the paths beyond its walls.\", \"type\": 1, \"markups\": [], \"alignment\": 1}]}, \"isFullContent\": false}, \"experimentalCss\": \"\", \"notifyFollowers\": true, \"previewContent2\": {\"subtitle\": \"Series: The Song of Kael\", \"bodyModel\": {\"sections\": [{\"name\": \"d784\", \"startIndex\": 0}], \"paragraphs\": [{\"name\": \"abac\", \"text\": \"EPISODE 2: THE SONG AND THE PRINCESS\", \"type\": 3, \"markups\": []}, {\"name\": \"bbb7\", \"text\": \"Series: The Song of Kael\", \"type\": 1, \"markups\": [{\"end\": 24, \"type\": 2, \"start\": 0}]}, {\"name\": \"a656\", \"text\": \"Layali wore a cloak too plain for a princess, slipping past guards and servants with the elegance only rebellion could teach. She knew the castle’s every corridor — but not the paths beyond its walls.\", \"type\": 1, \"markups\": []}, {\"name\": \"d0a6\", \"text\": \"Tonight, her curiosity was louder than her duty.\", \"type\": 1, \"markups\": []}, {\"name\": \"83ed\", \"text\": \"The melody…\", \"type\": 1, \"markups\": []}]}, \"isFullContent\": false}, \"responsesLocked\": false, \"webCanonicalUrl\": \"https://medium.com/@amowogbajeflorence/episode-2-the-song-and-the-princess-a7aebf219e55\", \"detectedLanguage\": \"en\", \"firstPublishedAt\": 1749806987578, \"homeCollectionId\": \"\", \"isLockedResponse\": false, \"isPublishToEmail\": false, \"lockedPostSource\": 0, \"latestPublishedAt\": 1749806987578, \"mongerRequestType\": 1, \"curationEligibleAt\": 0, \"inResponseToPostId\": \"\", \"isTitleSynthesized\": true, \"editorialPreviewDek\": \"\", \"hasUnpublishedEdits\": true, \"importedPublishedAt\": 0, \"isMarkedPaywallOnly\": false, \"proxyPostFaviconUrl\": \"\", \"isEligibleForRevenue\": false, \"isSubscriptionLocked\": false, \"responseDistribution\": 0, \"seriesLastAppendedAt\": 0, \"editorialPreviewTitle\": \"\", \"inResponseToRemovedAt\": 0, \"isApprovedTranslation\": false, \"proxyPostProviderName\": \"\", \"isBlockedFromHightower\": false, \"latestPublishedVersion\": \"2a24d9cab79f\", \"audioVersionDurationSec\": 0, \"translationSourcePostId\": \"\", \"approvedHomeCollectionId\": \"\", \"translationSourceCreatorId\": \"\", \"inResponseToMediaResourceId\": \"\", \"featureLockRequestAcceptedAt\": 0, \"isDistributionAlertDismissed\": false, \"responseHiddenOnParentPostAt\": 0, \"hightowerMinimumGuaranteeEndsAt\": 0, \"hightowerMinimumGuaranteeStartsAt\": 0}, \"shareKey\": \"f9f26ab59fe5a3bc5d7fea6b640565a0\", \"hideMeter\": false, \"references\": {\"User\": {\"5d9c968bd96d\": {\"bio\": \"Amowogbaje Florence writes immersive, soul-stirring fiction that weaves fantasy with spiritual truth. Checkout another Book on https://selfany.com/lezqqa\", \"name\": \"Amowogbaje Florence\", \"type\": \"User\", \"social\": {\"type\": \"Social\", \"userId\": \"5d9c968bd96d\", \"targetUserId\":