(3, 1, 3, 'https://medium.com/@amowogbajeflorence/episode-3-the-poisoned-crown-fd4c01a86f6c', NULL, 0, 0, NULL, '2026-07-02 12:16:17', '2026-07-02 12:16:17', '{\"b\": \"20260701-1919-root\", \"v\": 3, \"payload\": {\"mode\": \"canEdit\", \"value\": {\"id\": \"fd4c01a86f6c\", \"slug\": \"episode-3-the-poisoned-crown\", \"type\": \"Post\", \"vote\": false, \"title\": \"EPISODE 3: THE POISONED CROWN\", \"content\": {\"subtitle\": \"Series: The Song of Kael\", \"bodyModel\": {\"sections\": [{\"name\": \"147f\", \"startIndex\": 0}, {\"name\": \"115e\", \"startIndex\": 12}, {\"name\": \"2c99\", \"startIndex\": 24}, {\"name\": \"d43a\", \"startIndex\": 33}, {\"name\": \"b028\", \"startIndex\": 36}], \"paragraphs\": [{\"name\": \"e3ef\", \"text\": \"EPISODE 3: THE POISONED CROWN\", \"type\": 3, \"markups\": []}, {\"name\": \"be0b\", \"text\": \"Kael with his Harp\", \"type\": 4, \"layout\": 1, \"markups\": [], \"metadata\": {\"id\": \"1*xHCMkuRAOPgui0qFElPLMw.png\", \"originalWidth\": 1024, \"originalHeight\": 1536}}, {\"name\": \"60f4\", \"text\": \"Series: The Song of Kael\", \"type\": 1, \"markups\": [{\"end\": 24, \"type\": 2, \"start\": 0}]}, {\"name\": \"f14b\", \"text\": \"The palace of Elarin had not known mourning in years.\", \"type\": 1, \"markups\": []}, {\"name\": \"061c\", \"text\": \"But this night, the royal corridors were hushed — not by ceremony, but by fear.\", \"type\": 1, \"markups\": []}, {\"name\": \"1efe\", \"text\": \"King Orom had died.\", \"type\": 1, \"markups\": [{\"end\": 9, \"type\": 1, \"start\": 0}]}, {\"name\": \"0d6d\", \"text\": \"The word spread fast and quiet: “He passed in his sleep.” Yet Layali, his only daughter, knew better. Her father was a cautious man. A warrior turned ruler. Poison was the only blade that could reach him now.\", \"type\": 1, \"markups\": [{\"end\": 57, \"type\": 2, \"start\": 32}]}, {\"name\": \"486d\", \"text\": \"She stood beside his shrouded body, fists clenched.\", \"type\": 1, \"markups\": []}, {\"name\": \"a354\", \"text\": \"Kael had not seen her for days. Not since the night beneath the flame tree. He didn’t even know she was royalty until he followed the crowd into the capital gates and saw her draped in royal white, standing beside a corpse that once ruled nations.\", \"type\": 1, \"markups\": []}, {\"name\": \"b8af\", \"text\": \"“She lied,” he thought.\\n “No… she protected herself. As I did.”\", \"type\": 6, \"markups\": [{\"end\": 25, \"type\": 2, \"start\": 11}]}, {\"name\": \"8e61\", \"text\": \"But now, something deeper stirred in him. This wasn’t about heartbreak or deception.\", \"type\": 1, \"markups\": []}, {\"name\": \"c2e7\", \"text\": \"It was about calling.\", \"type\": 1, \"markups\": [{\"end\": 20, \"type\": 1, \"start\": 13}]}, {\"name\": \"aa52\", \"text\": \"That evening, Kael walked into the palace grounds unannounced.\", \"type\": 1, \"markups\": []}, {\"name\": \"3916\", \"text\": \"He wore no weapons. He didn’t need them. His presence alone was sharpened steel.\", \"type\": 1, \"markups\": []}, {\"name\": \"3489\", \"text\": \"The guards did not stop him. Something in his eyes told them this man was not to be questioned.\", \"type\": 1, \"markups\": [{\"end\": 94, \"type\": 2, \"start\": 74}]}, {\"name\": \"46ec\", \"text\": \"Layali was in the garden, silent.\", \"type\": 1, \"markups\": []}, {\"name\": \"b67f\", \"text\": \"“You’re not just a shepherd,” she said.\", \"type\": 6, \"markups\": [{\"end\": 39, \"type\": 2, \"start\": 0}]}, {\"name\": \"42fe\", \"text\": \"“And you’re not just a grieving daughter.”\", \"type\": 6, \"markups\": [{\"end\": 42, \"type\": 2, \"start\": 0}]}, {\"name\": \"7d3f\", \"text\": \"She looked up, eyes wet but burning.\", \"type\": 1, \"markups\": []}, {\"name\": \"0391\", \"text\": \"“My father was poisoned. And the ones who sit at his table smile too easily.”\", \"type\": 6, \"markups\": [{\"end\": 77, \"type\": 2, \"start\": 0}]}, {\"name\": \"39a8\", \"text\": \"Kael nodded slowly.\", \"type\": 1, \"markups\": []}, {\"name\": \"c71e\", \"text\": \"“Do you want truth?” he asked.\", \"type\": 6, \"markups\": [{\"end\": 30, \"type\": 2, \"start\": 0}]}, {\"name\": \"6d94\", \"text\": \"“I want justice.”\", \"type\": 6, \"markups\": [{\"end\": 17, \"type\": 2, \"start\": 0}]}, {\"name\": \"785d\", \"text\": \"“Then I will find it. But you must be ready — because justice cuts deeper than grief.”\", \"type\": 6, \"markups\": [{\"end\": 86, \"type\": 2, \"start\": 0}]}, {\"name\": \"f132\", \"text\": \"That night, Kael reawakened the man he had buried.\", \"type\": 1, \"markups\": []}, {\"name\": \"a828\", \"text\": \"The ghost. The shadow. The unseen blade.\", \"type\": 1, \"markups\": []}, {\"name\": \"a646\", \"text\": \"He found the steward who prepared the king’s wine. Tracked the servant who never returned from the cellar. Whispered to a street beggar who saw which noble visited the kitchen door under moonlight.\", \"type\": 1, \"markups\": []}, {\"name\": \"4d88\", \"text\": \"Within three nights, he returned with a name — and a vial.\", \"type\": 1, \"markups\": []}, {\"name\": \"8778\", \"text\": \"The same poison that killed Orom.\", \"type\": 1, \"markups\": []}, {\"name\": \"e356\", \"text\": \"He handed it to Layali.\", \"type\": 1, \"markups\": []}, {\"name\": \"6b60\", \"text\": \"“Elohim reveals what men bury,” Kael said.\", \"type\": 6, \"markups\": [{\"end\": 42, \"type\": 2, \"start\": 0}]}, {\"name\": \"9760\", \"text\": \"“Why are you doing this?” she asked. “You don’t even know my world.”\", \"type\": 6, \"markups\": [{\"end\": 68, \"type\": 2, \"start\": 0}]}, {\"name\": \"eb95\", \"text\": \"“I don’t need to know your palace,” Kael whispered. “I know your pain.”\", \"type\": 6, \"markups\": [{\"end\": 71, \"type\": 2, \"start\": 0}]}, {\"name\": \"c989\", \"text\": \"That night, Layali didn’t sleep.\\n And Kael didn’t sing.\", \"type\": 1, \"markups\": []}, {\"name\": \"0742\", \"text\": \"But the heavens stirred — because a war was rising.\", \"type\": 1, \"markups\": []}, {\"name\": \"264f\", \"text\": \"Not one of armies… yet.\\n But of thrones, shadows, and divine purpose reborn.\", \"type\": 1, \"markups\": []}, {\"name\": \"dff2\", \"text\": \"🕊️ To be continued…\", \"type\": 1, \"markups\": [{\"end\": 20, \"type\": 2, \"start\": 4}]}]}, \"postDisplay\": {\"coverless\": true}}, \"license\": 0, \"cardType\": 0, \"isSeries\": false, \"seoTitle\": \"\", \"virtuals\": {\"tags\": [{\"name\": \"Romance\", \"slug\": \"romance\", \"type\": \"Tag\", \"metadata\": {\"postCount\": 64060, \"coverImage\": {\"id\": \"1*Oe08cL4oV3p22oyh7MnhEA.jpeg\", \"originalWidth\": 736, \"originalHeight\": 981}}, \"postCount\": 64060}, {\"name\": \"Fantasy\", \"slug\": \"fantasy\", \"type\": \"Tag\", \"metadata\": {\"postCount\": 41155, \"coverImage\": {\"id\": \"1*0yA3Uk5uwmbuJxdirQDURA.jpeg\", \"alt\": \"The Tor Books cover for Jo Walton’s ‘Everybody’s Perfect.’\", \"originalWidth\": 1200, \"originalHeight\": 1841}}, \"postCount\": 41155}, {\"name\": \"Warriors\", \"slug\": \"warriors\", \"type\": \"Tag\", \"metadata\": {\"postCount\": 1377, \"coverImage\": {\"id\": \"0*ENyN09fOu9j6F8bM\", \"originalWidth\": 7823, \"originalHeight\": 4792, \"unsplashPhotoId\": \"8MhejqEghLk\"}}, \"postCount\": 1377}, {\"name\": \"Thrones\", \"slug\": \"thrones\", \"type\": \"Tag\", \"metadata\": {\"postCount\": 37, \"coverImage\": {\"id\": \"1*a4tu_o8hAYcGgzVydthchw.png\", \"originalWidth\": 1672, \"originalHeight\": 941}}, \"postCount\": 37}], \"links\": {\"entries\": [], \"version\": \"0.3\", \"generatedAt\": 1749914954521}, \"topics\": [{\"name\": \"Fiction\", \"slug\": \"fiction\", \"type\": \"Topic\", \"image\": {\"id\": \"1*s8IiITC03I9AcUb8aJQG_w@2x.jpeg\", \"originalWidth\": 6016, \"originalHeight\": 4000}, \"topicId\": \"76d64bb2132c\", \"seoTitle\": \"Fiction Writing — Medium\", \"createdAt\": 1491495941661, \"deletedAt\": 0, \"visibility\": 1, \"description\": \"True lies.\", \"relatedTags\": [], \"relatedTopics\": [], \"relatedTopi